from itertools import groupby

class Solution:
    def countBinarySubstrings(self, s: str) -> int:
        lengths = [sum(1 for _ in group) for _, group in groupby(s)]
        return sum(min(a, b) for a, b in zip(lengths, lengths[1:]))
